"""Schema 12: optional coordination metadata. No agency requirements are seeded.

Canonical permits, checklists, inspections, contacts, corrections and files remain
in their existing tables. Source revision dates live on the linked source.
Extension JSON is reserved for later verified metadata, never credentials.
"""
P = 'project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE'
S = "source_id INTEGER REFERENCES reg_sources(id) ON DELETE SET NULL,last_verified_date TEXT NOT NULL DEFAULT '',if_applicable INTEGER NOT NULL DEFAULT 0 CHECK(if_applicable IN(0,1)),verify_label TEXT NOT NULL DEFAULT 'Verify'"
J = "details_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(details_json))"
TABLES = {
'reg_project_settings': f"{P} UNIQUE,cgp_subject TEXT NOT NULL DEFAULT 'Undecided' CHECK(cgp_subject IN('Undecided','Yes','No','Not Applicable')),jurisdiction TEXT NOT NULL DEFAULT 'Other' CHECK(jurisdiction IN('City of Sacramento','Sacramento County unincorporated','Other')),sidebar_visible INTEGER NOT NULL DEFAULT 0 CHECK(sidebar_visible IN(0,1)),notes TEXT NOT NULL DEFAULT ''",
'reg_sources': "title TEXT NOT NULL,publisher TEXT NOT NULL DEFAULT '',source_kind TEXT NOT NULL DEFAULT '',document_revision_date TEXT NOT NULL DEFAULT '',url TEXT NOT NULL DEFAULT '',last_verified_date TEXT NOT NULL DEFAULT '',verification_status TEXT NOT NULL DEFAULT 'Verify',conflict_notes TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT ''",
'reg_project_roles': f"{P},contact_id INTEGER REFERENCES contacts(id) ON DELETE SET NULL,role TEXT NOT NULL,delegate_for_role TEXT NOT NULL DEFAULT '',eauthorization_status TEXT NOT NULL DEFAULT 'Unknown' CHECK(eauthorization_status IN('Unknown','Yes','No')),eauthorization_date TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT ''",
'reg_templates': f"template_key TEXT NOT NULL UNIQUE,jurisdiction_key TEXT NOT NULL,occupancy_type TEXT NOT NULL DEFAULT '',work_type TEXT NOT NULL DEFAULT '',permit_family TEXT NOT NULL DEFAULT '',title TEXT NOT NULL,{S},active INTEGER NOT NULL DEFAULT 1,builtin INTEGER NOT NULL DEFAULT 0,{J}",
'reg_template_items': f"template_id INTEGER NOT NULL REFERENCES reg_templates(id) ON DELETE CASCADE,item_key TEXT NOT NULL,title TEXT NOT NULL,check_kind TEXT NOT NULL DEFAULT '',{S},sort_order INTEGER NOT NULL DEFAULT 0,{J},UNIQUE(template_id,item_key)",
'reg_wb_sites': f"{P} UNIQUE,wdid TEXT NOT NULL DEFAULT '',regional_board TEXT NOT NULL DEFAULT '',permit_type TEXT NOT NULL DEFAULT '',risk_level TEXT NOT NULL DEFAULT '',sediment_risk TEXT NOT NULL DEFAULT '',receiving_water_risk TEXT NOT NULL DEFAULT '',combined_risk TEXT NOT NULL DEFAULT '',total_acres TEXT NOT NULL DEFAULT '',disturbed_acres TEXT NOT NULL DEFAULT '',construction_start TEXT NOT NULL DEFAULT '',grading_complete TEXT NOT NULL DEFAULT '',final_stabilization TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'Not Started',location_address TEXT NOT NULL DEFAULT '',latitude TEXT NOT NULL DEFAULT '',longitude TEXT NOT NULL DEFAULT '',r_inputs_fingerprint TEXT NOT NULL DEFAULT '',r_overall_text TEXT NOT NULL DEFAULT '',r_state TEXT NOT NULL DEFAULT '',k_text TEXT NOT NULL DEFAULT '',ls_text TEXT NOT NULL DEFAULT '',erosion_enabled INTEGER NOT NULL DEFAULT 0,notes TEXT NOT NULL DEFAULT '',{J}",
'reg_filings': f"{P},wb_site_id INTEGER REFERENCES reg_wb_sites(id) ON DELETE CASCADE,filing_type TEXT NOT NULL,regulatory_lane TEXT NOT NULL DEFAULT 'Water Board',reference TEXT NOT NULL DEFAULT '',prepared_by_contact_id INTEGER REFERENCES contacts(id) ON DELETE SET NULL,certifier_role_id INTEGER REFERENCES reg_project_roles(id) ON DELETE SET NULL,certifier_name_snapshot TEXT NOT NULL DEFAULT '',certifier_role_snapshot TEXT NOT NULL DEFAULT '',certifier_eauth_snapshot TEXT NOT NULL DEFAULT 'Unknown',certifier_eauth_date_snapshot TEXT NOT NULL DEFAULT '',readiness_flag TEXT NOT NULL DEFAULT 'Not Ready',status TEXT NOT NULL DEFAULT 'Draft',deadline TEXT NOT NULL DEFAULT '',submitted_date TEXT NOT NULL DEFAULT '',decision_date TEXT NOT NULL DEFAULT '',manual_fee TEXT NOT NULL DEFAULT '',currency TEXT NOT NULL DEFAULT 'USD',reason_for_change TEXT NOT NULL DEFAULT '',fields_changed_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(fields_changed_json)),report_period_start TEXT NOT NULL DEFAULT '',report_period_end TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',{S},{J}",
'reg_permit_details': f"register_id INTEGER NOT NULL UNIQUE REFERENCES registers(id) ON DELETE CASCADE,jurisdiction_key TEXT NOT NULL DEFAULT 'Other',permit_family TEXT NOT NULL DEFAULT '',occupancy_type TEXT NOT NULL DEFAULT '',work_type TEXT NOT NULL DEFAULT '',local_reference TEXT NOT NULL DEFAULT '',fire_district TEXT NOT NULL DEFAULT '',cycle_no INTEGER NOT NULL DEFAULT 1,stage TEXT NOT NULL DEFAULT '',current_template_id INTEGER REFERENCES reg_templates(id) ON DELETE SET NULL,related_wb_site_id INTEGER REFERENCES reg_wb_sites(id) ON DELETE SET NULL,related_wb_filing_id INTEGER REFERENCES reg_filings(id) ON DELETE SET NULL,valuation_total TEXT NOT NULL DEFAULT '',valuation_addition TEXT NOT NULL DEFAULT '',valuation_remodel TEXT NOT NULL DEFAULT '',currency TEXT NOT NULL DEFAULT 'USD',notes TEXT NOT NULL DEFAULT '',{J}",
'reg_document_requests': f"{P},register_id INTEGER REFERENCES registers(id) ON DELETE SET NULL,filing_id INTEGER REFERENCES reg_filings(id) ON DELETE SET NULL,requested_from_contact_id INTEGER REFERENCES contacts(id) ON DELETE SET NULL,title TEXT NOT NULL,needed_by TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'Requested' CHECK(status IN('Requested','Received','In Review','Needs Changes','Approved','N/A')),notes TEXT NOT NULL DEFAULT '',{S}",
'reg_inspection_details': f"register_id INTEGER NOT NULL UNIQUE REFERENCES registers(id) ON DELETE CASCADE,inspection_kind TEXT NOT NULL DEFAULT 'Building',inspection_date TEXT NOT NULL DEFAULT '',jurisdiction TEXT NOT NULL DEFAULT 'Other',result TEXT NOT NULL DEFAULT '' CHECK(result IN('','Pass','Fail','Correction','Partial','Cancelled')),qualifying_event TEXT NOT NULL DEFAULT 'Undecided',findings TEXT NOT NULL DEFAULT '',corrective_action TEXT NOT NULL DEFAULT 'Undecided',correction_id INTEGER REFERENCES issues(id) ON DELETE SET NULL,{S},notes TEXT NOT NULL DEFAULT ''",
'reg_requirement_details': f"requirement_id INTEGER NOT NULL UNIQUE REFERENCES permit_requirements(id) ON DELETE CASCADE,template_item_id INTEGER REFERENCES reg_template_items(id) ON DELETE SET NULL,template_key TEXT NOT NULL DEFAULT '',origin TEXT NOT NULL DEFAULT 'User',jurisdiction_key TEXT NOT NULL DEFAULT 'Other',hidden INTEGER NOT NULL DEFAULT 0,deleted INTEGER NOT NULL DEFAULT 0,{S},{J}",
'reg_city_records': f"{P},permit_register_id INTEGER REFERENCES registers(id) ON DELETE SET NULL,record_kind TEXT NOT NULL,reference TEXT NOT NULL DEFAULT '',parent_sub_id INTEGER REFERENCES reg_city_records(id) ON DELETE SET NULL,notes TEXT NOT NULL DEFAULT '',{J}",
'reg_review_cycles': f"{P},register_id INTEGER NOT NULL REFERENCES registers(id) ON DELETE CASCADE,cycle_no INTEGER NOT NULL DEFAULT 1,stage TEXT NOT NULL DEFAULT '',submitted_date TEXT NOT NULL DEFAULT '',agency_response_date TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',{J},UNIQUE(register_id,cycle_no)",
'reg_cycle_reviews': f"cycle_id INTEGER NOT NULL REFERENCES reg_review_cycles(id) ON DELETE CASCADE,discipline TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Open',contact_id INTEGER REFERENCES contacts(id) ON DELETE SET NULL,due_date TEXT NOT NULL DEFAULT '',response_date TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',{S}",
'reg_tracker_steps': f"{P},register_id INTEGER REFERENCES registers(id) ON DELETE CASCADE,filing_id INTEGER REFERENCES reg_filings(id) ON DELETE CASCADE,template_item_id INTEGER REFERENCES reg_template_items(id) ON DELETE SET NULL,step_key TEXT NOT NULL,title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Not Started',deadline TEXT NOT NULL DEFAULT '',occurred_date TEXT NOT NULL DEFAULT '',contact_id INTEGER REFERENCES contacts(id) ON DELETE SET NULL,cycle_id INTEGER REFERENCES reg_review_cycles(id) ON DELETE SET NULL,{S},notes TEXT NOT NULL DEFAULT '',hidden INTEGER NOT NULL DEFAULT 0,deleted INTEGER NOT NULL DEFAULT 0,sort_order INTEGER NOT NULL DEFAULT 0,{J}",
'reg_manual_charges': f"{P},register_id INTEGER REFERENCES registers(id) ON DELETE SET NULL,filing_id INTEGER REFERENCES reg_filings(id) ON DELETE SET NULL,title TEXT NOT NULL,amount TEXT NOT NULL DEFAULT '',currency TEXT NOT NULL DEFAULT 'USD',status TEXT NOT NULL DEFAULT 'Unpaid',paid_date TEXT NOT NULL DEFAULT '',{S},notes TEXT NOT NULL DEFAULT ''",
'reg_filing_changes': f"filing_id INTEGER NOT NULL REFERENCES reg_filings(id) ON DELETE CASCADE,field_name TEXT NOT NULL,previous_value TEXT NOT NULL DEFAULT '',revised_value TEXT NOT NULL DEFAULT '',source_id INTEGER REFERENCES reg_sources(id) ON DELETE SET NULL,notes TEXT NOT NULL DEFAULT ''",
'reg_rfactor_periods': f"wb_site_id INTEGER NOT NULL REFERENCES reg_wb_sites(id) ON DELETE CASCADE,position INTEGER NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,r_value_text TEXT NOT NULL DEFAULT '',calculated_on TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',needs_recalculation INTEGER NOT NULL DEFAULT 0,verification_flags_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(verification_flags_json)),inputs_fingerprint TEXT NOT NULL DEFAULT '',{S},UNIQUE(wb_site_id,position)",
'reg_rules': f"rule_key TEXT NOT NULL UNIQUE,title TEXT NOT NULL,body TEXT NOT NULL DEFAULT '',applies_to_role TEXT NOT NULL DEFAULT '',{S},origin TEXT NOT NULL DEFAULT 'User',builtin INTEGER NOT NULL DEFAULT 0,hidden INTEGER NOT NULL DEFAULT 0,deleted INTEGER NOT NULL DEFAULT 0,{J}",
'reg_rule_overrides': f"{P},rule_id INTEGER REFERENCES reg_rules(id) ON DELETE SET NULL,record_table TEXT NOT NULL,record_id INTEGER,warning_code TEXT NOT NULL,reason TEXT NOT NULL,occurred TEXT NOT NULL,user_label TEXT NOT NULL DEFAULT '',{J}",
'reg_template_tombstones': f"{P},register_id INTEGER REFERENCES registers(id) ON DELETE CASCADE,template_item_key TEXT NOT NULL,reason TEXT NOT NULL DEFAULT '',occurred TEXT NOT NULL,UNIQUE(project_id,register_id,template_item_key)",
}
SCHEMA = '\n'.join(f'CREATE TABLE {name}(id INTEGER PRIMARY KEY,{columns});' for name,columns in TABLES.items()) + '''
CREATE UNIQUE INDEX reg_city_one_per_sub ON reg_city_records(parent_sub_id) WHERE parent_sub_id IS NOT NULL;
CREATE UNIQUE INDEX reg_annual_period ON reg_filings(wb_site_id,report_period_start,report_period_end) WHERE filing_type='Annual Report';
CREATE INDEX reg_requests_due ON reg_document_requests(project_id,status,needed_by);
CREATE INDEX reg_steps_due ON reg_tracker_steps(project_id,status,deadline);
CREATE INDEX reg_filings_due ON reg_filings(project_id,status,deadline);
'''
# Obtain exact writable columns from SQLite rather than parsing SQL declarations.
def field_map():
 import sqlite3
 with sqlite3.connect(':memory:') as db:
  db.executescript(SCHEMA)
  return {t:[r[1] for r in db.execute(f'PRAGMA table_info({t})') if r[1]!='id'] for t in TABLES}
REG_FIELDS=field_map()
